(() => {
  const button=document.querySelector('#readBtn'); if(!button)return;
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  button.addEventListener('click',()=>setTimeout(()=>{const method=document.querySelector('.method.active')?.dataset.name,box=document.querySelector('.rich-method-result');if(!box||!['八字','印度占星'].includes(method))return;const topic=document.querySelector('#topicChoice')?.dataset.value||'工作',q=document.querySelector('#question')?.value.trim()||'目前最重要的選擇',raw=document.querySelector('#resultText')?.textContent||'';const evidence=method==='八字'?(raw.match(/八字計算[\s\S]{0,260}/)?.[0]||raw.slice(0,260)):(raw.match(/Lagna[\s\S]{0,360}/)?.[0]||raw.slice(0,360));const outlook={工作:'你要比較權責、資源、回饋及 90 日成果，不是只睇人工。',財運:'你要比較現金流、收入穩定、合約條件及最壞損失，不是只睇一筆高回報。',感情:'你要比較對方實際行動、溝通節奏、信任及界線，不是只睇一時心動。',健康:'你要先觀察睡眠、壓力及身體訊號；命理只作反思，健康問題要問醫護。','家庭／人際':'你要分清楚自己責任、對方責任及需要講清楚嘅界線。','學業／方向':'你要比較能力、興趣、資源及下一個可驗證成果。',其他:'你要將問題拆成已知、未知、風險及可以即刻驗證嘅一步。'}[topic];box.insertAdjacentHTML('beforeend',`<section class="personal-summary"><div class="rich-method-head"><span>PERSONAL SYNTHESIS</span><strong>墨川對「${esc(topic)}」嘅真正判讀</strong><small>問題：「${esc(q)}」</small></div><div class="personal-evidence"><b>盤面證據</b><pre>${esc(evidence)}</pre></div><div class="personal-grid"><div><b>表面性格</b><p>你會先整理資料、控制表情，表面上似乎唔急住要答案。</p></div><div><b>隱藏性格</b><p>你其實好怕揀錯後失去轉身空間，所以會反覆核對細節。</p></div><div><b>目前真正煩惱</b><p>你問緊「${esc(q)}」，核心係想知道代價由邊個承擔，以及自己仲有冇選擇權。</p></div><div><b>對${esc(topic)}嘅結論</b><p>${outlook}</p></div><div><b>可能時間段</b><p>未來 7 日適合收集事實及直接提問；未來 1 至 3 個月係調整方向、關係或資源配置嘅觀察窗口。屬於推測，唔係保證事件。</p></div><div><b>你下一步要做</b><p>今日寫低兩個方案，每個列出一項收益、一項代價、一個未知數，再只驗證最影響決定嘅未知數。</p></div></div></section>`);},620));
})();
